window.docContents[118].resolve({"/LindenstraussPolynomials/Core/#mod-doc-LindenstraussPolynomials___Core-1-0":{"contents":"The core of the proof\n\nFor every increasing n-tuple of almost norming points the geometric lemma gives a lower bound for the fully mixed value of the limit form (eq:vordered); iterated limits along an ultrafilter then turn these bounds into \\|\\widetilde Q(z)\\|\\ge\\|Q\\| at a point z of the unit ball of X^{**}.\n\n\n","context":"","header":"LindenstraussPolynomials.Core","id":"/LindenstraussPolynomials/Core/#mod-doc-LindenstraussPolynomials___Core-1-0"},"/LindenstraussPolynomials/Substitution/#LindenstraussPolynomials___re_integral_diag":{"contents":"The real part commutes with the integral. \n\n","context":"","header":"LindenstraussPolynomials.re_integral_diag","id":"/LindenstraussPolynomials/Substitution/#LindenstraussPolynomials___re_integral_diag"}});